import { diffLines } from "diff";

export interface FindReplace {
  find: string;
  replace: string;
}

export type EditComputation = { ok: true; content: string } | { ok: false; problems: string[] };

export const EDIT_LIMITS = {
  maxEditsPerCall: 20,
  maxFileBytes: 1024 * 1024,
};

/** Lockfiles are generated by package managers; editing them by hand breaks installs. */
const GENERATED_FILES = /(^|\/)(package-lock\.json|pnpm-lock\.yaml|yarn\.lock|bun\.lockb?)$/;

export function isGeneratedFile(relativePath: string): boolean {
  return GENERATED_FILES.test(relativePath);
}

/** Test files and manifests can be edited, but the approval card calls it out. */
export function editWarning(relativePath: string): string | null {
  if (/(^|\/)(test|tests|__tests__)\/|\.(test|spec)\.[cm]?[jt]sx?$/.test(relativePath)) {
    return "This changes a test file.";
  }
  if (/(^|\/)package\.json$/.test(relativePath)) return "This changes package.json.";
  return null;
}

function countOccurrences(haystack: string, needle: string): number {
  let count = 0;
  for (
    let i = haystack.indexOf(needle);
    i !== -1;
    i = haystack.indexOf(needle, i + needle.length)
  ) {
    count++;
  }
  return count;
}

/**
 * Applies exact find/replace edits in order. Each `find` must occur exactly
 * once in the text as it stands after the previous edits, so an edit can never
 * land in an ambiguous place. CRLF files keep their line endings.
 */
export function computeEdit(original: string, edits: FindReplace[]): EditComputation {
  if (edits.length === 0) return { ok: false, problems: ["No edits were given."] };
  if (edits.length > EDIT_LIMITS.maxEditsPerCall) {
    return {
      ok: false,
      problems: [`Too many edits (${edits.length}); the limit is ${EDIT_LIMITS.maxEditsPerCall}.`],
    };
  }
  const crlf = original.includes("\r\n");
  const problems: string[] = [];
  let content = original;

  edits.forEach((edit, i) => {
    const find = crlf ? edit.find.replace(/\r?\n/g, "\r\n") : edit.find;
    const replace = crlf ? edit.replace.replace(/\r?\n/g, "\r\n") : edit.replace;
    if (find.length === 0) {
      problems.push(`Edit ${i + 1}: "find" is empty.`);
      return;
    }
    if (find === replace) {
      problems.push(`Edit ${i + 1}: "find" and "replace" are identical.`);
      return;
    }
    const n = countOccurrences(content, find);
    if (n !== 1) {
      problems.push(
        `Edit ${i + 1}: the "find" text occurs ${n} times (it must occur exactly once). Re-read the file and copy the text exactly, with enough context to be unique: ${JSON.stringify(find.slice(0, 120))}`,
      );
      return;
    }
    content = content.replace(find, () => replace);
  });

  if (problems.length > 0) return { ok: false, problems };
  if (content === original) return { ok: false, problems: ["The edits make no change."] };
  if (new TextEncoder().encode(content).length > EDIT_LIMITS.maxFileBytes) {
    return { ok: false, problems: ["The result would be larger than 1 MB."] };
  }
  return { ok: true, content };
}

export function lineStats(before: string, after: string): { additions: number; deletions: number } {
  let additions = 0;
  let deletions = 0;
  for (const part of diffLines(before, after)) {
    if (part.added) additions += part.count ?? 0;
    if (part.removed) deletions += part.count ?? 0;
  }
  return { additions, deletions };
}
